import type { Register } from 'claude-code'

const MODELS = ['haiku', 'sonnet', 'opus', 'fable', 'default'] as const
const EFFORTS = ['low', 'medium', 'high', 'xhigh', 'max'] as const
const FULL_MODEL_ID = /^claude-[a-z0-9.-]+(\[1m\])?$/
const USAGE = 'Usage: /m <model> <effort>, /m <model>, or /m <effort>. Models: haiku, sonnet, opus, fable, default, or a claude-* id. Effort: low, medium, high, xhigh, max.'

type Plan = { model?: string; effort?: string } | { error: string }

export function plan(args: string): Plan {
  const words = args.trim().toLowerCase().split(/\s+/).filter(Boolean)
  if (words.length === 0 || words.length > 2) {
    return { error: USAGE }
  }

  let model: string | undefined
  let effort: string | undefined
  for (const word of words) {
    if ((EFFORTS as readonly string[]).includes(word) && effort === undefined) {
      effort = word
    } else if (((MODELS as readonly string[]).includes(word) || FULL_MODEL_ID.test(word)) && model === undefined) {
      model = word
    } else {
      return { error: `Unknown value "${word}". ${USAGE}` }
    }
  }

  return { model, effort }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'm', description: 'Switch model and effort at once: /m haiku low' })

    return next(e)
  })

  on('command.run', { command: 'm' }, async ($, e) => {
    const chosen = plan(e.args)
    if ('error' in chosen) {
      return { text: chosen.error }
    }

    // A command.run hook cannot run another command itself; a timer runs them once this one has finished.
    $.clock.after(0, async () => {
      try {
        if (chosen.model !== undefined) {
          await $.command.run({ command: 'model', args: chosen.model })
        }
        if (chosen.effort !== undefined) {
          await $.command.run({ command: 'effort', args: chosen.effort })
        }
      } catch (err) {
        await $.ui.toast(`/m failed: ${String(err)}`)
      }
    })

    return { text: `Switching to ${[chosen.model, chosen.effort].filter(Boolean).join(' · ')}` }
  })
}
